import { 
  MeshBasicNodeMaterial, 
  DoubleSide,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  AmbientLight
} from 'three/webgpu';
import { 
  uv, 
  texture, 
  positionLocal, 
  normalLocal, 
  vec3, 
  uniform 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // --- STAGE BACKDROP ---
  // Create solid dark surface backboard (~7x6 units at z=-2.5) to satisfy W-PCP §9
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const backGeom = new PlaneGeometry(7.2, 5.8);
  const backMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    side: DoubleSide,
    depthWrite: false
  });
  const backdrop = new Mesh(backGeom, backMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- LOCAL LIGHTS (Rim + Key) ---
  const keyLight = new DirectionalLight(colors.paper, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colors.accent, 1.4);
  rimLight.position.set(-3, -3, -1);
  group.add(rimLight);

  const ambientLight = new AmbientLight(colors.ink, 0.4);
  group.add(ambientLight);

  // --- TEXTURED PARALLAX PLANE WITH DISPLACEMENT ---
  // 64x64 segments segment plane for high detailed TSL vertex-displacement mapping
  const width = 3.6;
  const height = 2.25;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  const material = new MeshBasicNodeMaterial({
    side: DoubleSide
  });

  // Create TSL Uniforms for controlling displacement depth dynamically
  const displacementScale = uniform(0.18);

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load physical maps
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      material.colorNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // TSL Vertex position displacement along the normal vector
      const depthVal = texture(depthTex, uv()).r;
      const displacedPos = positionLocal.add(normalLocal.mul(depthVal.mul(displacementScale)));
      material.positionNode = displacedPos;
      material.needsUpdate = true;
    });
  }

  // --- CONTAMINANT CHIPS (Decorative subtle divider & Pricing detail elements) ---
  // Thin polished metal accent line right below the main displaced graphic card context
  const dividerGeom = new PlaneGeometry(width, 0.02);
  const dividerMat = new MeshBasicNodeMaterial({ color: colors.paper, opacity: 0.25, transparent: true });
  const divider = new Mesh(dividerGeom, dividerMat);
  divider.position.set(0, -(height/2 + 0.15), 0.05);
  group.add(divider);

  // Accent edge notch
  const accentGeom = new PlaneGeometry(0.12, 0.02);
  const accentMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const accentNotch = new Mesh(accentGeom, accentMat);
  accentNotch.position.set(-(width/2 - 0.06), -(height/2 + 0.15), 0.06);
  group.add(accentNotch);

  // --- BRAND / ATELIER LABELS (Verbatim spec metadata rendering) ---
  const pricingLabel = ctx.fontAtlas.createText("NOVA PRICING tier-1", {
    fontSize: 0.08,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 2
  });
  pricingLabel.position.set(-width/2 + 0.05, height/2 - 0.14, 0.1);
  group.add(pricingLabel);

  const specLabel = ctx.fontAtlas.createText("01 MACHINED METALS", {
    fontSize: 0.065,
    color: colors.accent,
    align: 'right',
    letterSpacingPx: 1
  });
  specLabel.position.set(width/2 - 0.05, -height/2 + 0.06, 0.1);
  group.add(specLabel);

  // --- PRIMITIVES BINDINGS ---
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primRef = ctx.primitives[primitive.name](mesh, primitive.params);
        if (primRef) activePrimitives.push(primRef);
      }
    });
  }

  // --- INTERACTION SIGNATURES ---
  let isHovered = false;

  group.userData.handlers = {
    pointerover: () => {
      isHovered = true;
      gsap.to(mesh.position, {
        y: 0.15,
        z: 0.08,
        duration: 0.4,
        ease: 'power3.out'
      });
      gsap.to(displacementScale, {
        value: 0.28,
        duration: 0.5,
        ease: 'power2.out'
      });
      gsap.to(dividerMat, {
        opacity: 0.7,
        duration: 0.3
      });
    },
    pointerout: () => {
      isHovered = false;
      gsap.to(mesh.position, {
        y: 0,
        z: 0,
        duration: 0.6,
        ease: 'power4.out'
      });
      gsap.to(displacementScale, {
        value: 0.18,
        duration: 0.6,
        ease: 'power4.out'
      });
      gsap.to(dividerMat, {
        opacity: 0.25,
        duration: 0.4
      });
    },
    click: () => {
      gsap.timeline()
        .to(mesh.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.08, ease: 'power2.out' })
        .to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.22, ease: 'back.out(2)' });

      ctx.emit('hub-pricing.select', {
        id: config.id,
        tier: 'T1',
        origin: 'pricing-list-row'
      });
    }
  };

  // --- TEARDOWN / CLEANUP ---
  group.userData.cleanup = () => {
    activePrimitives.forEach(prim => {
      if (prim && typeof prim.cleanup === 'function') prim.cleanup();
    });
    gsap.killTweensOf([mesh.position, mesh.scale, displacementScale, dividerMat]);
    geometry.dispose();
    material.dispose();
    backGeom.dispose();
    backMat.dispose();
    dividerGeom.dispose();
    dividerMat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
  };

  return group;
}
